#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
FILES=("$GSZ/views/partials/store_top.ejs" "$GSZ/views/partials/store_bottom.ejs" "$GSZ/views/home.ejs" "$GSZ/views/trials.ejs" "$GSZ/views/account/trials.ejs")
echo "==> step174: Browse hover-bridge + 'IPTV Free Trial' relabel + trial modal 2-up"
BKS=()
for F in "${FILES[@]}"; do [ -f "$F" ] && { cp "$F" "$F.bak-step174-$TS"; BKS+=("$F"); }; done
echo "    backups: *.bak-step174-$TS"
restore(){ echo "!! restoring"; for F in "${BKS[@]}"; do cp "$F.bak-step174-$TS" "$F" 2>/dev/null||true; done; }
trap 'restore' ERR
PATCHER=$(mktemp /tmp/patch_step174.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying"; NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"
echo "==> validating ejs"
for F in "${BKS[@]}"; do NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$F','utf8'),{filename:'$F'});console.log('    ok: '+'$F'.replace('$GSZ/',''))"; done
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$PATCHER"; trap - ERR
echo ""
echo "==> step174 OK  Browse menu stays open on hover-down; label is now 'IPTV Free Trial'; trial modal shows 2 per row (1 on small phones). Just reload."
